import { mkdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const outputDirectory = fileURLToPath(new URL("../tests/fixtures/photos/", import.meta.url));
const jpeg = Buffer.from(
  "",
  "base64",
);

await mkdir(outputDirectory, { recursive: true });
await Promise.all(
  Array.from({ length: 30 }, (_, index) =>
    writeFile(`${outputDirectory}/photo-${String(index + 1).padStart(2, "0")}.jpg`, jpeg),
  ),
);

console.log(`Generated 30 deterministic JPEG fixtures in ${outputDirectory}`);
